  "inlineSchema": "datasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// 1. Client Inquiries & Commercial Proposals\nmodel Inquiry {\n  id                String    @id @default(uuid())\n  inquiryCode       String    @unique\n  client            String\n  project           String\n  amount            Float\n  contactPerson     String?\n  email             String?\n  phone             String?\n  date              DateTime  @default(now())\n  status            String // \"Inquiry Received\", \"Offer Sent\", \"Confirmed\", \"Unconfirmed\"\n  holdStatus        Boolean   @default(false)\n  holdReason        String?\n  heldAt            DateTime?\n  remarks           String?\n  startDate         DateTime?\n  estimatedDuration Int? // Duration in days\n  projectLead       String?\n  weeksAgo          Int       @default(1)\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  orders      Order[]\n  wbsTasks    WBSTask[]\n  teamMembers ProjectTeam[]\n}\n\n// 2. Confirmed Orders & Manufacturing Jobs\nmodel Order {\n  id           String   @id @default(uuid())\n  orderNumber  String   @unique\n  inquiryId    String?\n  inquiry      Inquiry? @relation(fields: [inquiryId], references: [id])\n  clientName   String\n  projectName  String\n  panels       String // Comma separated or JSON string\n  priority     String // \"High\", \"Medium\", \"Low\"\n  currentStage String // e.g. \"Mechanical Dept.\"\n  progress     Int      @default(0)\n  startDate    DateTime\n  deadline     DateTime\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  phaseRemarks    PhaseRemark[]\n  phaseChecklists PhaseChecklist[]\n  materials       MaterialRequest[]\n}\n\n// 3. Work Breakdown Structure (WBS) Phases & Tasks\nmodel WBSPhase {\n  id      String    @id @default(uuid())\n  wbsCode String    @unique\n  name    String\n  badge   String\n  owner   String\n  tasks   WBSTask[]\n}\n\nmodel WBSTask {\n  id          String   @id @default(uuid())\n  wbsCode     String\n  name        String\n  phaseId     String\n  phase       WBSPhase @relation(fields: [phaseId], references: [id], onDelete: Cascade)\n  inquiryId   String?\n  inquiry     Inquiry? @relation(fields: [inquiryId], references: [id], onDelete: SetNull)\n  owner       String\n  planHours   Float\n  actualHours Float    @default(0)\n  status      String // \"DONE\", \"IN PROGRESS\", \"NOT STARTED\"\n  progress    Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// 4. Production Phase Department Checklists & Remarks\nmodel PhaseRemark {\n  id        String   @id @default(uuid())\n  orderId   String?\n  order     Order?   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  phaseId   String // e.g. \"assembly\"\n  remark    String\n  updatedAt DateTime @updatedAt\n}\n\nmodel PhaseChecklist {\n  id        String  @id @default(uuid())\n  orderId   String?\n  order     Order?  @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  phaseId   String // e.g. \"design\", \"mechanical\", \"assembly\"\n  taskId    Int\n  taskName  String\n  completed Boolean @default(false)\n}\n\n// 5. Staff & Employee Directory (With Microsoft OAuth SSO support)\nmodel Employee {\n  id           String   @id @default(uuid())\n  empCode      String   @unique\n  name         String\n  email        String   @unique\n  passwordHash String\n  department   String\n  designation  String\n  role         String\n  isAdmin      Boolean  @default(false)\n  permissions  String   @default(\"{}\")\n  status       String\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  attendances  Attendance[]\n  projectTeams ProjectTeam[]\n}\n\nmodel Attendance {\n  id         String   @id @default(uuid())\n  employeeId String\n  employee   Employee @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  date       DateTime @default(now())\n  clockIn    String?\n  clockOut   String?\n  status     String // \"Present\", \"Late\", \"On Leave\"\n}\n\n// 6. Material Requisitions & Inventory\nmodel MaterialRequest {\n  id            String   @id @default(uuid())\n  requestCode   String   @unique\n  orderId       String?\n  order         Order?   @relation(fields: [orderId], references: [id], onDelete: SetNull)\n  itemName      String\n  quantity      Int\n  requestedBy   String\n  requestedDate DateTime @default(now())\n  status        String // \"Pending\", \"Approved\", \"Rejected\"\n}\n\n// 7. Project Teams and Resource Allocation\nmodel ProjectTeam {\n  id         String   @id @default(uuid())\n  inquiryId  String\n  inquiry    Inquiry  @relation(fields: [inquiryId], references: [id], onDelete: Cascade)\n  employeeId String\n  employee   Employee @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  role       String // \"Lead\", \"Member\"\n  assignedAt DateTime @default(now())\n  assignedBy String? // Admin/Manager ID who assigned them\n\n  @@unique([inquiryId, employeeId])\n}\n",
